app.post('/api/users', (req, res) => {
  const { email, password } = req.body;

  // 1. 400 Bad Request (Client forgot to send data!)
  if (!email || !password) {
    return res.status(400).json({ error: "Email and password are required" });
  }

  // 2. 401 Unauthorized (Client sent a bad password!)
  if (password !== 'secret123') {
    return res.status(401).json({ error: "Invalid credentials. Please log in." });
  }

  // 3. 403 Forbidden (Client is logged in, but not an admin!)
  if (req.user.role !== 'Admin') {
    return res.status(403).json({ error: "You are not allowed to create users." });
  }

  res.status(200).send("Success");
});
